'use strict';
(() => {
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',layers:'<path d="m12 3 9 5-9 5-9-5zM3 12l9 5 9-5M3 16l9 5 9-5"/>',folder:'<path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/>',book:'<path d="M12 5v16M3 3c4-1 7 0 9 2 2-2 5-3 9-2v16c-4-1-7 0-9 2-2-2-5-3-9-2z"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 8.5a2.5 2.5 0 1 1 3 2.5c-.5.2-.5 1-.5 2M12 16h.01"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',back:'<path d="M19 12H5m5-5-5 5 5 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4L19 6"/>',file:'<path d="M13 3H5v18h14V9zM13 3v6h6M8 13h8M8 17h6"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H4v13h4"/>',save:'<path d="M4 3h13l4 4v14H3V3zM7 3v6h10V3M7 21v-8h10v8"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',edit:'<path d="m15 4 5 5M4 20l4-1L21 6a2 2 0 0 0-5-5L3 14z"/>',print:'<path d="M6 8V3h12v5M6 17H3V8h18v9h-3M6 13h12v8H6zM17 10h1"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M9 10v7M15 10v7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z"/>',upload:'<path d="M12 16V3m-4 4 4-4 4 4M4 16v5h16v-5"/>'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.file}</svg>`;
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=(x)=>JSON.parse(JSON.stringify(x));
const $=(q,root=document)=>root.querySelector(q);
const $$=(q,root=document)=>[...root.querySelectorAll(q)];
const templates=window.LESSON_TEMPLATES;
const BLOOM=['Remember','Understand','Apply','Analyze','Evaluate','Create'];
const TITLES=['Lesson title','Learning outcomes','Bloom levels','Teaching strategies','Learning resources','Key concepts & terms','Lead-in','Lesson procedures','Formative assessment','Final assessment'];
const COURSES={L1:'Level 1',L2:'Level 2',L3:'Level 3',TW:'Technical Writing',TC:'Technical Communication',PS:'Public Speaking'};
let worksheetCode='L1',worksheetMode='student',worksheetReturn='worksheets',printOverride=false;
const STORE='lesson-rush-lessons-v1',DRAFT='lesson-rush-draft-v1';
let storageOK=true,saved=[],current=null,page='curriculum',tab='edit',filter='All',query='',toastTimer,draftTimer;
function storageRead(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{storageOK=false;return fallback}}
function storageWrite(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{storageOK=false;return false}}
function validPlan(p){return p&&typeof p==='object'&&typeof p.name==='string'&&typeof p.code==='string'&&Object.hasOwn(COURSES,p.code)&&Array.isArray(p.outcomes)&&p.outcomes.length<=30&&p.outcomes.every(r=>Array.isArray(r)&&r.length===3&&r.every(c=>typeof c==='string'))&&Array.isArray(p.stages)&&p.stages.length<=50&&p.stages.every(r=>Array.isArray(r)&&r.length===4&&r.every(c=>typeof c==='string'||typeof c==='number'))}
const stored=storageRead(STORE,[]);saved=Array.isArray(stored)?stored.filter(validPlan):[];
const oldDraft=storageRead(DRAFT,null);current=validPlan(oldDraft)?oldDraft:null;
function uid(){return window.crypto?.randomUUID?.()||`plan-${Date.now()}-${Math.random().toString(36).slice(2,9)}`}
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function fillIcons(){ $$('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon)); }
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3400)}
function dateLabel(date){if(!date)return 'Date not set';try{return new Date(date+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})}catch{return date}}
function updatedLabel(date){if(!date)return '';const d=new Date(date);return Number.isNaN(+d)?'':d.toLocaleDateString('en-GB',{day:'numeric',month:'short'})}
function setDraft(){if(!current)return;const ok=storageWrite(DRAFT,current);const s=$('#draft-label');if(s)s.textContent=ok?'Draft saved on this device':'Storage unavailable — download a backup';}
function scheduleDraft(){clearTimeout(draftTimer);draftTimer=setTimeout(setDraft,350);}
function setPath(path,val){const keys=path.split('.');let t=current;for(const k of keys.slice(0,-1))t=t[k];t[keys.at(-1)]=val;}
function getPath(path){return path.split('.').reduce((o,k)=>o?.[k],current)??''}
function normalize(p){const d=clone(p);d.id=typeof d.id==='string'?d.id:uid();d.teacher=typeof d.teacher==='string'?d.teacher:'Ms. Amina Qatan';d.date=typeof d.date==='string'?d.date:today();d.group=typeof d.group==='string'?d.group:'';d.duration=Math.min(300,Math.max(5,Number(d.duration)||60));d.reflection=typeof d.reflection==='string'?d.reflection:'';['unit','focus','reference','strategies','resources','prior','terms','model','checks','lead','material','formative','final','support','extension','home'].forEach(k=>{if(typeof d[k]!=='string')d[k]=''});d.blooms=Array.isArray(d.blooms)?d.blooms.filter(b=>BLOOM.includes(b)):(d.bloom||'').split('|').map(s=>s.trim()).filter(b=>BLOOM.includes(b));d.stages=d.stages.map(r=>r.map(String));return d;}
if(current)current=normalize(current);saved=saved.map(normalize);
function newPlan(code,blank=false){const p=clone(templates.find(t=>t.code===code)||templates[0]);p.id=uid();p.teacher='Ms. Amina Qatan';p.date=today();p.group='';p.duration=60;p.reflection='';p.blooms=p.bloom.split('|').map(x=>x.trim());if(blank){p.name='';p.unit='';p.focus='';p.reference='';p.blooms=[];p.outcomes=[['','','']];p.stages=[['5','Lead-in','',''],['10','Model / clarify','',''],['15','Guided practice','',''],['25','Independent task','',''],['5','Final check','','']];['strategies','resources','prior','terms','model','checks','lead','material','formative','final','support','extension','home'].forEach(k=>p[k]='')};current=p;setDraft();tab='edit';navigate('editor');}
function navigate(next){if(next==='home')next='curriculum';if($('#dialog').open)closeModal();clearTimeout(draftTimer);if(current)setDraft();page=next;query='';filter='All';$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');render();window.scrollTo(0,0);}
function warning(){return storageOK?'':'<div class="storage-warning">Browser storage is unavailable. Keep your work by downloading a backup before leaving.</div>'}
function render(){const nav=page==='packs'?'packs':'curriculum';$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===nav));$('#saved-count').textContent=saved.length;$('#breadcrumb').textContent=({home:'Your planning space',templates:'Find your starting point',saved:'Your lesson collection',guide:'A little guidance goes a long way',editor:'Your lesson workspace',worksheets:'From plan to practice',worksheet:'Your classroom handout',toolkit:'Your teaching studio',packs:'Ready packs',curriculum:'Build a lesson'})[page]||'';const views={home:homeView,templates:templatesView,saved:savedView,guide:guideView,editor:editorView,worksheets:worksheetsView,worksheet:worksheetView,toolkit:toolkitView,packs:()=>window.PackStudio.packsView(),curriculum:()=>window.PackStudio.curriculumView()};$('#main').innerHTML=warning()+views[page]();fillIcons();if(page==='editor')updateStatus();window.PackStudio?.afterRender(page);}
function card(t,i){return `<button class="course-card tone-${['purple','orange','pink'][i%3]}" data-template="${t.code}"><div class="course-top"><span class="course-badge">${t.code}</span><span class="course-type">${i<3?'General English':'Professional skills'}</span></div><h3>${esc(t.course)}</h3><p>${esc(t.name)}</p><div class="course-foot"><span>${icon('clock')}60 min · Preview lesson</span><span class="arrow-circle">${icon('arrow')}</span></div></button>`}
function courseGrid(){const q=query.toLowerCase();return templates.map((t,i)=>({t,i})).filter(({t})=>(filter==='All'||t.code===filter)&&`${t.course} ${t.name} ${t.code} ${t.unit}`.toLowerCase().includes(q)).map(({t,i})=>card(t,i)).join('')||'<p class="no-results">No matching templates. Try another course or topic.</p>'}
function homeView(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">LESSON RUSH · ENGLISH LESSON PLANNER</div><h1>Good lessons.<br><em>Less rush.</em></h1><p>From a first idea to a classroom-ready plan.<br>Your teaching, with a little more breathing room.</p><div class="hero-actions"><button class="btn btn-orange" data-action="new">${icon('plus')}Create a lesson</button><button class="btn btn-quiet" data-nav="templates">Explore templates ${icon('arrow')}</button></div></div><div class="hero-art studio-hero-art" aria-label="Teaching shortcuts"><div class="hero-halo"></div><span class="hero-spark spark-one" aria-hidden="true">✦</span><span class="hero-spark spark-two" aria-hidden="true">✧</span><button class="floating-note note-goal" data-action="outcome-builder"><span class="note-icon">${icon('spark')}</span><span><small>START WITH THE WHY</small><strong>One clear goal.</strong><em>Build a learning outcome ${icon('arrow')}</em></span></button><button class="floating-note note-practice" data-nav="toolkit"><span class="note-icon">${icon('book')}</span><span><small>MAKE LEARNING HAPPEN</small><strong>Meaningful practice.</strong><em>Find a classroom activity ${icon('arrow')}</em></span></button><button class="floating-note note-check" data-action="review-lesson"><span class="note-icon">${icon('check')}</span><span><small>SEE THE PROGRESS</small><strong>A moment to check.</strong><em>Connect task and evidence ${icon('arrow')}</em></span></button></div></section>
<div class="quick-facts"><button data-nav="templates">${icon('layers')}<span><strong>6 course templates</strong><small>A purposeful starting point</small></span>${icon('arrow')}</button><button data-action="outcome-builder">${icon('spark')}<span><strong>Build a clear outcome</strong><small>Make success observable</small></span>${icon('arrow')}</button><button data-nav="worksheets">${icon('file')}<span><strong>Classroom-ready practice</strong><small>Worksheets + teacher keys</small></span>${icon('arrow')}</button></div>
<section><div class="section-heading"><div><h2>A head start for every course</h2><p>Choose a lesson example. Make it your own.</p></div><span class="section-label">YOUR CURRICULUM, CONNECTED</span></div><div class="course-grid">${courseGrid()}</div></section>
<section class="worksheet-banner"><div><span class="eyebrow">FROM PLAN TO PRACTICE</span><h2>A worksheet for every lesson.</h2><p>Six student handouts, with separate teacher keys and PDF downloads.</p></div><button class="btn btn-orange" data-nav="worksheets">${icon('file')}Browse worksheets ${icon('arrow')}</button></section>
<section class="worksheet-banner"><div><span class="eyebrow">YOUR COMPLETE PLANNING COLLECTION</span><h2>15 units. 75 daily lesson plans.</h2><p>Read the books, adapt a daily plan, or fill in your own lesson.</p></div><div class="toolbar-actions"><button class="btn btn-primary" data-nav="packs">Lesson packs</button><button class="btn btn-secondary" data-nav="curriculum">Build a lesson</button></div></section><section class="recent-section"><div class="section-heading"><div><h2>Pick up where you left off</h2><p>A space for the lessons you're making.</p></div><button class="btn btn-quiet" data-nav="saved">View all ${icon('arrow')}</button></div>${current?`<div class="empty-inline"><div class="empty-icon">${icon('edit')}</div><div><h3>${esc(current.name||'Your untitled lesson')}</h3><p>${esc(COURSES[current.code])} · Current draft on this device</p></div><button class="btn btn-secondary" data-action="resume">Continue planning ${icon('arrow')}</button></div>`:saved.length?`<div class="saved-list">${saved.slice(0,2).map(savedRow).join('')}</div>`:`<div class="empty-inline"><div class="empty-icon">${icon('folder')}</div><div><h3>Your next great lesson starts here.</h3><p>Create a plan and save it to find it here next time.</p></div><button class="btn btn-secondary" data-action="new">Let's get started ${icon('arrow')}</button></div>`}</section>`}
function filterBar(){return `<div class="filter-bar" role="group" aria-label="Filter by course">${['All',...Object.keys(COURSES)].map(c=>`<button class="chip ${filter===c?'active':''}" data-filter="${c}" aria-pressed="${filter===c}">${c==='All'?'All courses':c}</button>`).join('')}</div>`}
function templatesView(){return `<div class="page-title"><div><div class="eyebrow muted">A THOUGHTFUL STARTING POINT</div><h1>Lesson templates</h1><p>Six worked examples, connected to the course materials.</p></div><button class="btn btn-primary" data-action="new">${icon('plus')}Start from blank</button></div><label class="searchbar">${icon('search')}<input id="search" type="search" aria-label="Search templates" placeholder="Search a course, topic or skill…" value="${esc(query)}"></label>${filterBar()}<div class="course-grid" id="course-results">${courseGrid()}</div><div class="notice">These are editable lesson examples, not a complete curriculum generator. Timings and success criteria are proposed teaching choices. The TW example is based on the available assessment task. Open the Planning guide for source details.</div>`}
function savedRow(p){return `<article class="saved-row"><span class="course-badge">${esc(p.code)}</span><div class="saved-info"><h3>${esc(p.name||'Untitled lesson')}</h3><p>${esc(p.group||'Group not set')} · ${dateLabel(p.date)} · ${p.duration} min${p.updatedAt?' · Saved '+updatedLabel(p.updatedAt):''}</p></div><div class="row-actions"><button class="btn btn-soft" data-open="${esc(p.id)}">Open ${icon('arrow')}</button><button class="icon-button" data-duplicate="${esc(p.id)}" aria-label="Duplicate ${esc(p.name||'lesson')}">${icon('copy')}</button><button class="icon-button" data-delete="${esc(p.id)}" aria-label="Delete ${esc(p.name||'lesson')}">${icon('trash')}</button></div></article>`}
function filteredSaved(){const matches=saved.filter(p=>(filter==='All'||p.code===filter)&&`${p.name} ${p.code} ${p.group}`.toLowerCase().includes(query.toLowerCase()));return matches.map(savedRow).join('')||'<p class="no-results">No lessons match your search.</p>'}
function savedView(){return `<div class="page-title"><div><h1>My lessons</h1><p>Your saved collection · ${saved.length} ${saved.length===1?'lesson':'lessons'} on this device</p></div><button class="btn btn-primary" data-action="new">${icon('plus')}Create a lesson</button></div>${saved.length?`<label class="searchbar">${icon('search')}<input id="search" type="search" aria-label="Search saved lessons" placeholder="Find a lesson or group…"></label>${filterBar()}<div id="saved-results" class="saved-list">${filteredSaved()}</div>`:`<div class="blank-state"><div class="empty-icon">${icon('folder')}</div><h2>A home for your best lessons.</h2><p>Choose a template or start from blank, then select “Save lesson” to keep it in your collection.</p><button class="btn btn-primary" data-nav="templates">Explore templates ${icon('arrow')}</button></div>`}<div class="notice">Saved lessons stay in this browser on this device. Download a backup to keep a separate copy or move your plans to another device.<div class="data-actions"><button class="btn btn-secondary" data-action="backup">${icon('download')}Download collection</button><button class="btn btn-secondary" data-action="import">${icon('upload')}Import backup</button></div></div>`}
function field(path,label,opts={}){let value=getPath(path);const id='field-'+path.replaceAll('.','-');return `<div class="field"><label for="${id}">${esc(label)}</label>${opts.options?`<select id="${id}" data-path="${path}">${opts.empty?'<option value="">Choose a level</option>':''}${opts.options.map(v=>`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`:opts.area?`<textarea id="${id}" data-path="${path}" rows="${opts.rows||3}" placeholder="${esc(opts.placeholder||'')}">${esc(value)}</textarea>`:`<input id="${id}" data-path="${path}" type="${opts.type||'text'}" value="${esc(value)}" ${opts.type==='number'?`min="${opts.min??1}" max="${opts.max??300}"`:''} placeholder="${esc(opts.placeholder||'')}">`}${opts.hint?`<div class="field-hint">${esc(opts.hint)}</div>`:''}</div>`}
function section(n,html){return `<section class="edit-section" id="section-${n}"><div class="edit-heading"><span class="number">${String(n).padStart(2,'0')}</span><h2>${TITLES[n-1]}</h2><button class="section-tip" data-section-tip="${n}" aria-label="Planning tip for ${TITLES[n-1]}">${icon('help')}</button><button class="copy-field" data-copy-field="${n}" aria-label="Copy ${TITLES[n-1]}">${icon('copy')}</button></div>${html}</section>`}
function outcomesForm(){return current.outcomes.map((r,i)=>`<div class="outcome-row"><div class="outcome-top">OUTCOME ${i+1}<button class="remove-btn" data-remove-outcome="${i}" aria-label="Remove outcome ${i+1}">${icon('close')}</button></div>${field(`outcomes.${i}.0`,'Students will be able to…',{area:true,rows:2,placeholder:'Use an observable action: identify, compare, write…'})}<div class="field-grid">${field(`outcomes.${i}.1`,'Bloom level',{options:BLOOM,empty:true})}${field(`outcomes.${i}.2`,'Success evidence',{area:true,rows:2,placeholder:'What will show that students achieved it?'})}</div></div>`).join('')+`<button class="text-button" data-action="add-outcome">${icon('plus')}Add learning outcome</button>`}
function stageForm(){return current.stages.map((r,i)=>`<div class="stage"><div class="stage-top"><strong>STAGE ${String(i+1).padStart(2,'0')}</strong><button class="remove-btn" data-remove-stage="${i}" aria-label="Remove stage ${i+1}">${icon('close')}</button></div><div class="field-grid">${field(`stages.${i}.0`,'Minutes',{type:'number',min:0})}${field(`stages.${i}.1`,'Stage')}</div>${field(`stages.${i}.2`,'Teacher and student actions',{area:true,rows:2})}${field(`stages.${i}.3`,'Learning evidence',{area:true,rows:2})}</div>`).join('')+`<button class="text-button" data-action="add-stage">${icon('plus')}Add stage</button><div class="total-line" id="stage-total"></div><button class="text-button" data-action="fit-time">Fit stage timings to lesson duration</button><p class="field-hint">The lead-in and final check are included in this sequence. Count each once.</p>`}
function editForm(){return `<section class="edit-section"><div class="edit-heading"><span class="number">${icon('file')}</span><h2>The essentials</h2></div><div class="field-grid">${field('teacher','Teacher')}${field('group','Group / class',{placeholder:'e.g. IE · Group A'})}</div><div class="field-grid three">${field('code','Course',{options:Object.keys(COURSES)})}${field('date','Lesson date',{type:'date'})}${field('duration','Duration (minutes)',{type:'number',min:5})}</div>${field('unit','Unit / curriculum area')}${field('focus','Skill focus',{placeholder:'e.g. Speaking and short writing'})}</section>
${section(1,field('name','Lesson title',{placeholder:'Give your lesson a clear, useful title'}))}
${section(2,'<button class="btn btn-soft builder-entry" data-action="outcome-builder">Build an outcome</button><p class="field-hint" style="margin-bottom:14px">By the end of the lesson, students will be able to…</p>'+outcomesForm())}
${section(3,`<div class="chips-select">${BLOOM.map(b=>`<label><input type="checkbox" data-bloom="${b}" ${current.blooms.includes(b)?'checked':''}>${b}</label>`).join('')}</div><p class="field-hint">Choose the thinking levels your tasks require. Keep these aligned with your outcomes.</p>`)}
${section(4,field('strategies','Teaching approaches',{area:true,placeholder:'Pair work, guided practice, information gap…'}))}
${section(5,field('resources','Resources and materials',{area:true,placeholder:'Coursebook pages, visuals, handouts, board…'}))}
${section(6,field('terms','Vocabulary and language focus',{area:true})+field('prior','Prior learning',{area:true,rows:2})+field('model','Model language',{area:true,rows:4})+field('checks','Meaning, form and pronunciation checks',{area:true,rows:3}))}
${section(7,field('lead','Set the context',{area:true,placeholder:'How will you engage students and activate prior knowledge?'}))}
${section(8,stageForm()+field('material','Classroom task material / prompts',{area:true,rows:4}))}
${section(9,field('formative','Check during learning',{area:true,placeholder:'What will you check, and how will you respond?'}))}
${section(10,field('final','End-of-lesson task and success criteria',{area:true}))}
<section class="edit-section" id="section-support"><div class="edit-heading"><span class="number">${icon('spark')}</span><h2>Make it work for your learners</h2></div>${field('support','Support / differentiation',{area:true,rows:2})}${field('extension','Extension',{area:true,rows:2})}${field('home','Follow-up task',{area:true,rows:2})}${field('reflection','After the lesson: reflection',{area:true,rows:3,placeholder:'What evidence shows success? What will you change next time?'})}${field('reference','Curriculum connection / source',{area:true,rows:3,hint:'If you change the course or topic, update this reference too.'})}</section>`}
function editorView(){if(!current){page='curriculum';return homeView()}return `<div class="toolbar"><button class="back-link" data-nav="templates">${icon('back')}Back to templates</button><div class="toolbar-actions"><button class="btn btn-soft" data-action="review-lesson">${icon('check')}Review</button><button class="btn btn-secondary" data-action="teach-mode">${icon('clock')}Teach</button><button class="btn btn-secondary" data-related-worksheet="${esc(current.code)}">${icon('file')}Worksheet</button><button class="btn btn-secondary" data-action="copy-all">${icon('copy')}Copy all</button><button class="btn btn-secondary" data-action="export">${icon('download')}Export</button><button class="btn btn-primary" data-action="save">${icon('save')}Save lesson</button></div></div><div class="editor-title"><div class="eyebrow muted">${esc(current.code)} · YOUR LESSON, YOUR WAY</div><h1 id="editor-name">${esc(current.name||'A fresh start')}</h1><p>Edit the sections, check the flow, and make the plan your own.</p></div><div class="editor-layout"><div class="editor-main"><div class="editor-tabs" role="tablist" aria-label="Lesson view"><button class="tab ${tab==='edit'?'active':''}" data-tab="edit" role="tab" aria-selected="${tab==='edit'}">${icon('edit')}Edit plan</button><button class="tab ${tab==='preview'?'active':''}" data-tab="preview" role="tab" aria-selected="${tab==='preview'}">${icon('eye')}Preview</button></div>${tab==='edit'?editForm():`<div class="paper-preview">${planHTML(current)}</div>`}<div class="editor-bottom"><button class="btn btn-secondary" data-action="print">${icon('print')}Print / Save PDF</button><button class="btn btn-primary" data-action="save">${icon('save')}Save lesson</button></div></div><aside class="editor-aside"><div class="readiness"><h3>Your plan at a glance</h3><div class="progress-count"><span id="complete-number">0</span> <small>/ 10 sections</small></div><div class="progress-track"><span id="complete-progress"></span></div><div class="section-jump" id="section-jump"></div></div><div class="time-check" id="time-check"></div><div class="studio-aside"><strong>A little teaching inspiration?</strong><p>Open an activity, adapt it and add it to this plan.</p><button class="btn btn-soft" data-nav="toolkit">${icon('spark')}Teaching studio</button></div><details class="source-card"><summary>Curriculum connection</summary><p id="source-content">${esc(current.reference||'Add a unit outcome or source reference for this custom lesson.')}</p><p>Activities, timings and success criteria are editable teaching choices.${current.code==='TW'?' This example uses the available TW assessment task.':''}</p></details><div class="draft-status"><span class="status-dot"></span><span id="draft-label">${storageOK?'Draft saved on this device':'Download a backup to keep your work'}</span></div></aside></div>`}
function completion(){const p=current,has=s=>String(s||'').trim().length>0;return [has(p.name),p.outcomes.some(r=>has(r[0])&&has(r[2])),p.blooms.length>0,has(p.strategies),has(p.resources),has(p.terms),has(p.lead),p.stages.some(r=>has(r[1])&&has(r[2])),has(p.formative),has(p.final)]}
function totalTime(){return current.stages.reduce((s,r)=>s+(Number(r[0])||0),0)}
function updateStatus(){if(page!=='editor'||!current)return;const c=completion(),count=c.filter(Boolean).length,total=totalTime();$('#complete-number').textContent=count;$('#complete-progress').style.width=count*10+'%';$('#section-jump').innerHTML=TITLES.map((t,i)=>`<a href="#section-${i+1}" data-jump="${i+1}" class="${c[i]?'done':''}"><span class="mini-check">${c[i]?'✓':''}</span>${t}</a>`).join('');$('#time-check').innerHTML=`<strong>${icon('clock')} ${total} / ${Number(current.duration)||0} minutes</strong>${total===Number(current.duration)?'The lesson timings add up. You’re ready to check the flow.':`Your stages ${total>current.duration?'run over by':'need another'} ${Math.abs(total-current.duration)} minutes. Adjust the stages or the duration.`}`;const time=$('#stage-total');if(time){time.classList.toggle('warning',total!==Number(current.duration));time.innerHTML=`<span>Planned lesson time</span><strong>${total} / ${Number(current.duration)||0} min</strong>`}$('#editor-name').textContent=current.name||'A fresh start';$('#source-content').textContent=current.reference||'Add a unit outcome or source reference for this custom lesson.';}
function textSection(n,p=current){switch(n){case 1:return p.name;case 2:return p.outcomes.map((r,i)=>`${i+1}. ${r[0]}\nBloom: ${r[1]}\nEvidence: ${r[2]}`).join('\n\n');case 3:return p.blooms.join(' · ');case 4:return p.strategies;case 5:return p.resources;case 6:return p.terms;case 7:return p.lead;case 8:return p.stages.map(r=>`${r[0]} min | ${r[1]}\n${r[2]}\nEvidence: ${r[3]}`).join('\n\n');case 9:return p.formative;case 10:return p.final;default:return ''}}
function planText(p=current){return `${p.name||'Untitled lesson'}\nSalalah Vocational College\n${COURSES[p.code]} | ${p.unit}\nTeacher: ${p.teacher}\nGroup: ${p.group}\nDate: ${p.date} | Duration: ${p.duration} minutes\n\n`+TITLES.map((t,i)=>`${i+1}. ${t.toUpperCase()}\n${textSection(i+1,p)}`).join('\n\n')+`\n\nPRIOR LEARNING\n${p.prior}\n\nMODEL LANGUAGE\n${p.model}\n\nLANGUAGE CHECKS\n${p.checks}\n\nCLASSROOM MATERIAL\n${p.material}\n\nSUPPORT\n${p.support}\n\nEXTENSION\n${p.extension}\n\nFOLLOW-UP\n${p.home}\n\nREFLECTION\n${p.reflection}\n\nCURRICULUM CONNECTION\n${p.reference}\n\nDeveloped by: Ms. Amina Qatan 2026 · Lesson Rush`;}
function planHTML(p){const content=s=>String(s||'').trim()?esc(s):'<span class="missing">Not yet added</span>';const table=(heads,rows,cls='')=>`<table class="${cls}"><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${content(c)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;const sec=(n,html)=>`<section><h2>${n}. ${TITLES[n-1]}</h2>${html}</section>`;return `<article class="plan-doc"><div class="print-brand">LESSON RUSH · SALALAH VOCATIONAL COLLEGE</div><h1>${esc(p.name||'Untitled lesson')}</h1><table class="metadata-table"><tbody><tr><td><b>COURSE / UNIT</b>${esc(COURSES[p.code])}<br>${esc(p.unit)}</td><td><b>TEACHER / GROUP</b>${esc(p.teacher)}<br>${esc(p.group||'Group not set')}</td></tr><tr><td><b>DATE / DURATION</b>${esc(dateLabel(p.date))} · ${p.duration} minutes</td><td><b>SKILL FOCUS</b>${content(p.focus)}</td></tr></tbody></table>${sec(1,`<p>${content(p.name)}</p>`)}${sec(2,table(['Students will be able to…','Bloom level','Success evidence'],p.outcomes))}${sec(3,`<p>${content(p.blooms.join(' · '))}</p>`)}${sec(4,`<p>${content(p.strategies)}</p>`)}${sec(5,`<p>${content(p.resources)}</p>`)}${sec(6,`<p>${content(p.terms)}</p>${p.prior?`<p><strong>Prior learning:</strong> ${esc(p.prior)}</p>`:''}${p.model?`<div class="extra-note"><p><strong>Model language</strong><br>${esc(p.model)}</p></div>`:''}${p.checks?`<p><strong>Language checks:</strong> ${esc(p.checks)}</p>`:''}`)}${sec(7,`<p>${content(p.lead)}</p>`)}${sec(8,table(['Min','Stage','Teacher and student actions','Learning evidence'],p.stages,'procedure-table')+(p.material?`<div class="extra-note"><p><strong>Classroom material</strong><br>${esc(p.material)}</p></div>`:''))}${sec(9,`<p>${content(p.formative)}</p>`)}${sec(10,`<p>${content(p.final)}</p>`)}<section><h2>Support, follow-up and reflection</h2>${[['Support',p.support],['Extension',p.extension],['Follow-up',p.home],['Reflection',p.reflection]].map(([k,v])=>`<p><strong>${k}:</strong> ${content(v)}</p>`).join('')}</section><p class="source-note"><strong>Curriculum connection:</strong> ${content(p.reference)}</p><div class="plan-footer">Developed by: Ms. Amina Qatan 2026 · Lesson Rush</div></article>`}
function guideView(){return `<div class="page-title"><div><div class="eyebrow muted">PLAN WITH PURPOSE</div><h1>A little structure. More possibility.</h1><p>Keep the outcome, task and evidence connected.</p></div></div><div class="guide-grid"><article class="guide-card"><span class="number">01</span><h3>Start with what students will do.</h3><p>Choose one course outcome, then narrow it to a lesson-sized task. Use observable verbs and specify the evidence you will collect.</p><ul><li>Outcome: request a tool and explain its use.</li><li>Task: a requester–storekeeper dialogue.</li><li>Evidence: a suitable tool and a clear reason.</li></ul></article><article class="guide-card"><span class="number">02</span><h3>Give every stage a purpose.</h3><p>Lead in, clarify or model, guide practice, then let students work more independently. Check progress as the lesson unfolds.</p><ul><li>Include student actions, not only teacher actions.</li><li>Count the lead-in and final check once.</li><li>Allow time for feedback and transitions.</li></ul></article><article class="guide-card"><span class="number">03</span><h3>Choose Bloom levels thoughtfully.</h3><p>Remember → Understand → Apply → Analyze → Evaluate → Create.</p><p>The level depends on the thinking required by the task. A lesson need not include every level. Keep the selected levels consistent with your outcomes.</p></article><article class="guide-card"><span class="number">04</span><h3>Make assessment useful.</h3><p>Use a formative check to decide what to explain or practise next. Finish with evidence linked to the outcome: an exchange, written response, report section or short talk.</p><p>The final lesson check is separate from a formal course examination.</p></article><article class="guide-card guide-wide"><h3>Where the examples begin</h3><ul class="source-list">${templates.map(p=>`<li><strong>${p.code} · ${esc(p.course)}</strong><br>${esc(p.reference)}</li>`).join('')}</ul><div class="notice">The six templates are worked lesson examples. They do not represent every unit or all official assessment requirements. TW is based on an available Industrial Electricity assessment task. Classroom cases and the L3 data are teaching examples, not actual college records.</div></article><article class="guide-card guide-wide"><h3>Your plans, ready to travel</h3><p>“Save lesson” keeps a copy in My lessons on this browser. Export a Word-compatible document, print or choose “Save as PDF” in the print dialog. A JSON backup lets you move editable plans between devices.</p><div class="data-actions"><button class="btn btn-secondary" data-action="backup">${icon('download')}Download collection</button><button class="btn btn-secondary" data-action="import">${icon('upload')}Import backup</button></div></article></div>`}
function modal(title,body,actions='',variant=''){const d=$('#dialog');if(variant!=='teach-dialog')stopTeaching();d.className=variant;$('#dialog-content').innerHTML=`<div class="dialog-inner"><div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}${actions?`<div class="dialog-actions">${actions}</div>`:''}</div>`;if(!d.open)d.showModal();}
function closeModal(){stopTeaching();$('#dialog').close()}
function newDialog(){modal('A fresh start.',`<p>Choose your course. You’ll get a blank, editable plan with all ten essential sections.</p><div class="field"><label for="new-course">Course</label><select id="new-course">${Object.entries(COURSES).map(([c,n])=>`<option value="${c}">${c} · ${n}</option>`).join('')}</select></div>`,`<button class="btn btn-secondary" data-action="close">Cancel</button><button class="btn btn-primary" data-action="create-blank">Create lesson ${icon('arrow')}</button>`)}
function help(){modal('Two simple ways to plan.',`<ol><li><strong>Build a lesson:</strong> fill in a guided form, one section at a time. Save your lesson and print it when ready.</li><li><strong>Ready packs:</strong> choose Level 1, 2 or 3, then a unit and day. Open the plan, worksheet, teacher notes or resources.</li></ol><p><strong>Teacher notes</strong> explain the approach, strategy and technique and include five minutes before and after class.</p><p><strong>Save plan</strong> keeps your work on this browser. Use Print & download for PDF or an editable backup.</p>`)}
function saveLesson(){if(!current.name.trim()){toast('Add a lesson title before saving.');tab='edit';render();$('#field-name')?.focus();return}const p=clone(current);p.updatedAt=new Date().toISOString();const i=saved.findIndex(x=>x.id===p.id);const next=clone(saved);if(i<0)next.unshift(p);else next[i]=p;if(!storageWrite(STORE,next)){toast('Unable to save here. Export a backup to keep your plan.');render();return}saved=next;current=p;setDraft();$('#saved-count').textContent=saved.length;toast('Lesson saved to My lessons on this device.');}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Copied. Ready to paste.')}catch{modal('Copy your lesson',`<p>Select and copy the text below.</p><div class="field"><textarea id="copy-fallback" rows="12" readonly>${esc(text)}</textarea></div>`);$('#copy-fallback').select()}}
function download(content,type,name){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function filename(){return (current.name||'Lesson Plan').replace(/[^a-zA-Z0-9 _-]/g,'').trim().replace(/\s+/g,'_')||'Lesson_Plan'}
function backup(all=true){const plans=all?saved:[current];if(!plans.length){toast('Save a lesson first, then download your collection.');return}download(JSON.stringify({app:'Lesson Rush',version:1,exportedAt:new Date().toISOString(),lessons:plans},null,2),'application/json',all?'Lesson_Rush_Collection.json':filename()+'.json');toast('Editable backup downloaded.');}
function exportDialog(){modal('Ready for the classroom.',`<p>Choose how you’d like to take this lesson with you.</p><div class="data-actions"><button class="btn btn-primary" data-action="print">${icon('print')}Print / Save PDF</button><button class="btn btn-secondary" data-action="word">${icon('file')}Word (.doc)</button><button class="btn btn-secondary" data-action="text">${icon('file')}Plain text</button><button class="btn btn-secondary" data-action="backup-current">${icon('download')}Editable backup</button></div><p style="margin-top:17px">For a PDF, choose “Save as PDF” in your browser’s print dialog. The Word-compatible file opens in Microsoft Word. Import a backup into Lesson Rush to edit it here.</p>`)}
function word(){const html=`<!DOCTYPE html><html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word"><head><meta charset="utf-8"><title>${esc(current.name)}</title><style>body{font-family:Arial,sans-serif;color:#30213e;font-size:11pt}h1{font-size:22pt}h2{font-size:12pt;background:#eee6f9;padding:7pt}table{border-collapse:collapse;width:100%;font-size:10pt}td,th{border:1px solid #d7c8e7;padding:7pt;text-align:left;vertical-align:top}th{background:#eee6f9}p{line-height:1.5;white-space:pre-wrap}.metadata-table b{display:block}.source-note,.plan-footer{font-size:9pt;color:#78638c}</style></head><body>${planHTML(current)}</body></html>`;download('\ufeff'+html,'application/msword',filename()+'.doc');toast('Word-compatible document downloaded.');}
function printPlan(){if(!current)return;printOverride=false;closeModal();$('#print-area').innerHTML=planHTML(current);setDraft();window.print();}
function fitTime(){const target=Math.max(current.stages.length,Math.round(Number(current.duration)||60));if(!current.stages.length){toast('Add a stage first.');return}current.duration=target;const weights=current.stages.map(r=>Math.max(0,Number(r[0])||0)),total=weights.reduce((a,b)=>a+b,0)||weights.length;let remainder=target-current.stages.length;const shares=weights.map(w=>remainder*(w||(!weights.some(Boolean)?1:0))/total),mins=shares.map(x=>Math.floor(x)+1);let left=target-mins.reduce((a,b)=>a+b,0);const order=shares.map((s,i)=>({i,f:s-Math.floor(s)})).sort((a,b)=>b.f-a.f);for(let i=0;i<left;i++)mins[order[i%order.length].i]++;current.stages.forEach((r,i)=>r[0]=String(mins[i]));setDraft();render();$('#section-8')?.scrollIntoView({block:'start'});toast('Stage timings updated. Review the pace for your class.');}
function confirmDelete(id){const p=saved.find(p=>p.id===id);if(!p)return;modal('Delete this saved lesson?',`<p>“${esc(p.name)}” will be removed from My lessons on this device. Other saved lessons will stay as they are.</p>`,`<button class="btn btn-secondary" data-action="close">Keep lesson</button><button class="btn btn-danger" data-confirm-delete="${esc(id)}">Delete lesson</button>`)}

function worksheetsView(){return `<div class="page-title"><div><div class="eyebrow muted">FROM PLAN TO PRACTICE</div><h1>Classroom worksheets</h1><p>Ready-to-use practice for each of the six lesson examples.</p></div></div><div class="course-grid">${window.LESSON_WORKSHEETS.map((w,i)=>`<button class="course-card worksheet-card tone-${['purple','orange','pink'][i%3]}" data-worksheet="${w.code}"><div class="course-top"><span class="course-badge">${w.code}</span><span class="course-type">2 student pages</span></div><h3>${esc(w.title)}</h3><p>${esc(w.description)}</p><div class="worksheet-skill">${esc(w.skills)}</div><div class="course-foot"><span>${icon('file')}Worksheet + teacher key</span><span class="arrow-circle">${icon('arrow')}</span></div></button>`).join('')}</div><div class="notice">Each worksheet matches its original Lesson Rush example. If you change the topic of a lesson, review the worksheet before using it. The TW worksheet follows the available assessment task. Student PDFs contain no answer keys.</div>`}
function openWorksheet(code,returnTo='worksheets'){if(!window.LessonRushWorksheets.get(code))return;worksheetCode=code;worksheetMode='student';worksheetReturn=returnTo;navigate('worksheet')}
function worksheetView(){const w=window.LessonRushWorksheets.get(worksheetCode);const key=worksheetMode==='key';return `<div class="toolbar"><button class="back-link" data-action="worksheet-back">${icon('back')}${worksheetReturn==='editor'?'Back to your lesson':'All worksheets'}</button><div class="toolbar-actions"><a class="btn btn-primary" href="worksheets/${w.code}_${key?'Teacher_Key':'Student_Worksheet'}.pdf" download>${icon('download')}Download ${key?'key':'worksheet'} PDF</a><button class="btn btn-secondary" data-action="${key?'print-key':'print-worksheet'}">${icon('print')}Print / Save PDF</button><button class="btn btn-secondary" data-action="worksheet-word">${icon('file')}Word (.doc)</button></div></div><div class="editor-title"><div class="eyebrow muted">${w.code} · CLASSROOM PRACTICE</div><h1>${esc(w.title)}</h1><p>${key?'Teacher guidance and suggested responses.':'Two student pages with activities, answer spaces and a self-check.'}</p></div><div class="editor-tabs worksheet-tabs" role="tablist" aria-label="Worksheet version"><button class="tab ${!key?'active':''}" data-worksheet-mode="student" role="tab" aria-selected="${!key}">${icon('file')}Student worksheet</button><button class="tab ${key?'active':''}" data-worksheet-mode="key" role="tab" aria-selected="${key}">${icon('check')}Teacher key</button></div>${key?'<div class="worksheet-key-notice">Teacher copy — suggested answers are included in this version.</div>':''}<div class="worksheet-preview">${window.LessonRushWorksheets.html(w.code,worksheetMode)}</div>`}
function printWorksheet(mode){printOverride=true;closeModal();$('#print-area').innerHTML=window.LessonRushWorksheets.html(worksheetCode,mode);window.print()}
function worksheetWord(){const key=worksheetMode==='key';const html=`<!DOCTYPE html><html xmlns:w="urn:schemas-microsoft-com:office:word"><head><meta charset="utf-8"><title>${esc(window.LessonRushWorksheets.get(worksheetCode).title)}</title><style>body{font-family:Arial;font-size:11pt;color:#352348}h1{font-size:21pt}h3{font-size:12pt;color:#674396}p{white-space:pre-wrap;line-height:1.5}.worksheet-header{border-bottom:2pt solid #a47bd4;padding-bottom:10pt}.worksheet-logo{font-weight:bold}.worksheet-course{margin-left:15pt}.worksheet-student-meta{margin:15pt 0}.worksheet-student-meta span{margin-right:15pt}.worksheet-section{margin-top:15pt}.worksheet-box{background:#fff3dd;border:1pt solid #e8cbaa;padding:10pt;white-space:pre-wrap}.worksheet-table{border-collapse:collapse;width:100%;margin-top:8pt}.worksheet-table td,.worksheet-table th{border:1pt solid #d5c5e5;padding:8pt;text-align:left;min-height:25pt}.worksheet-table th{background:#eee6f9}.worksheet-lines div{height:21pt;border-bottom:1pt solid #c8b7d8}.worksheet-drawing{height:80pt;border:1pt solid #c8b7d8}.worksheet-sheet{page-break-after:always}.worksheet-sheet:last-child{page-break-after:auto}.worksheet-footer{border-top:1pt solid #d5c5e5;margin-top:15pt;padding-top:8pt;font-size:8pt}.worksheet-footer span{margin-right:20pt}.worksheet-source{font-size:9pt}.worksheet-checkbox{display:inline-block;width:9pt;height:9pt;border:1pt solid #888;margin-right:5pt}</style></head><body>${window.LessonRushWorksheets.html(worksheetCode,worksheetMode)}</body></html>`;download('\ufeff'+html,'application/msword',`${worksheetCode}_${key?'Teacher_Key':'Student_Worksheet'}.doc`);toast('Word-compatible worksheet downloaded.')}

const studio=window.LESSON_STUDIO;
let activityCategory='All',pendingDraftAction=null;
let outcomeDraft={level:'Apply',verb:'use',topic:'',condition:'',evidence:''};
const teaching={index:0,remaining:0,deadline:0,running:false,interval:null,planId:null};
function lessonPeek(code){const p=templates.find(t=>t.code===code);if(!p)return;modal(p.name,`<div class="popup-course"><span class="course-badge">${p.code}</span><div><strong>${esc(p.course)}</strong><p>${esc(p.unit)}</p></div><span class="popup-tag">60 minutes</span></div><p>${esc(p.focus)}</p><div class="popup-section"><h3>What students will do</h3><ul class="goal-list">${p.outcomes.map(r=>`<li><span>${icon('check')}</span><div>${esc(r[0])}<small>${esc(r[2])}</small></div></li>`).join('')}</ul></div><div class="popup-split"><div><span class="tiny-label">THINKING LEVELS</span><div class="tag-list">${p.bloom.split('|').map(s=>`<span>${esc(s.trim())}</span>`).join('')}</div></div><div><span class="tiny-label">CLASSROOM PACK</span><p>Editable plan · 2-page worksheet · Separate answer key</p></div></div><details class="popup-source"><summary>Curriculum connection</summary><p>${esc(p.reference)}</p></details>`,`<button class="btn btn-secondary" data-open-worksheet="${code}">${icon('file')}View worksheet</button><button class="btn btn-primary" data-use-template="${code}">${icon('spark')}Use this lesson</button>`,'wide-dialog')}
function worksheetPeek(code,from='worksheets'){const w=window.LessonRushWorksheets.get(code);if(!w)return;modal(w.title,`<div class="popup-course"><span class="course-badge">${code}</span><div><strong>Student worksheet + teacher key</strong><p>${esc(w.skills)}</p></div></div><p>${esc(w.description)}</p><div class="worksheet-mini-preview"><span>${icon('file')}</span><div><strong>Two pages. One clear learning goal.</strong><p>Name and group fields, guided practice, answer spaces and a final check.</p></div></div><div class="popup-section"><h3>Inside the worksheet</h3><ol>${w.pages.map(p=>`<li><strong>${esc(p.label)}</strong><br>${esc(p.sections.slice(0,3).map(s=>s.title).join(' · '))}</li>`).join('')}</ol></div><div class="download-pair"><a class="btn btn-soft" href="worksheets/${code}_Student_Worksheet.pdf" download>${icon('download')}Student PDF</a><a class="btn btn-secondary" href="worksheets/${code}_Teacher_Key.pdf" download>${icon('download')}Teacher key PDF</a></div>`,`<button class="btn btn-primary" data-open-worksheet="${code}" data-return-to="${from}">${icon('eye')}Open worksheet</button>`,'wide-dialog')}
function toolCard(action,iconName,label,desc,tone){return `<button class="studio-tool tone-${tone}" data-action="${action}"><span class="studio-tool-icon">${icon(iconName)}</span><h3>${label}</h3><p>${desc}</p><span class="tool-link">Open tool ${icon('arrow')}</span></button>`}
function toolkitView(){return `<div class="page-title"><div><div class="eyebrow">THE TEACHING STUDIO</div><h1>Small tools. Thoughtful lessons.</h1><p>Build a goal, find a useful activity and check how the pieces connect.</p></div><button class="btn btn-secondary" data-action="quick-actions">${icon('spark')}Quick actions</button></div><div class="studio-tools">${toolCard('outcome-builder','spark','Build an outcome','Choose a thinking level and make success observable.','purple')}${toolCard('review-lesson','check','Review your lesson','Check missing details, timing and alignment prompts.','pink')}${toolCard('teach-mode','clock','Teach in focus','One stage at a time, with a timer you control.','orange')}</div><div class="section-heading studio-section-heading"><div><h2>An activity for the moment</h2><p>Open a card for steps, learning evidence and ways to use it.</p></div><span class="section-label">9 PRACTICAL ROUTINES</span></div><div class="filter-bar" aria-label="Activity categories">${['All','Engage','Practise','Check','Support'].map(c=>`<button class="chip ${activityCategory===c?'active':''}" data-activity-category="${c}" aria-pressed="${activityCategory===c}">${c}</button>`).join('')}</div><div class="activity-grid" id="activity-results">${activityCards()}</div>`}
function activityCards(){return studio.activities.filter(a=>activityCategory==='All'||a.category===activityCategory).map(a=>`<button class="activity-card" data-activity="${a.id}"><div><span class="activity-category">${a.category}</span><span class="activity-time">${a.minutes?a.minutes+' min':'Adapt the task'}</span></div><h3>${a.title}</h3><p>${a.purpose}</p><span class="tool-link">${a.group} ${icon('arrow')}</span></button>`).join('')}
function activityPeek(id){const a=studio.activities.find(x=>x.id===id);if(!a)return;modal(a.title,`<div class="tag-list"><span>${a.category}</span><span>${a.group}</span><span>${a.minutes?a.minutes+' minutes':'Differentiation'}</span></div><p style="margin-top:16px">${a.purpose}</p><ol class="numbered-steps">${a.steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="evidence-box"><span class="tiny-label">WHAT TO LOOK FOR</span><p>${a.evidence}</p></div><p class="tool-materials"><strong>Prepare:</strong> ${a.resources}</p>${current?`<p class="current-lesson-label">Add to: <strong>${esc(current.name||'Your untitled lesson')}</strong></p>`:'<p>Open or create a lesson to add this activity to a plan. You can copy the routine now.</p>'}`,`<button class="btn btn-secondary" data-copy-activity="${id}">${icon('copy')}Copy routine</button><button class="btn btn-primary" data-add-activity="${id}" ${!current?'disabled':''}>${icon('plus')}${a.target==='stage'?'Add teaching stage':a.target==='support'?'Add support note':'Add extension'}</button>`,'wide-dialog')}
function addActivity(id){const a=studio.activities.find(x=>x.id===id);if(!a||!current)return;if(a.target==='stage'){if(current.stages.length>=50)return toast('This lesson already has 50 stages.');const row=[String(a.minutes),a.title,a.steps.join(' ')+' Prepare: '+a.resources,a.evidence];const last=current.stages.length-1;const idx=last>=0&&/final|exit/i.test(current.stages[last][1])?last:current.stages.length;current.stages.splice(idx,0,row)}else{const text=a.steps.join(' ');current[a.target]=[current[a.target],text].filter(Boolean).join('\n\n')}setDraft();closeModal();tab='edit';navigate('editor');if(a.target==='stage')$('#section-8')?.scrollIntoView({block:'start'});toast(a.target==='stage'?'Activity added. Check the total lesson time.':'Differentiation note added to your lesson.');}
function outcomeSentence(){const t=outcomeDraft.topic.trim().replace(/[.!?]+$/,'');const c=outcomeDraft.condition.trim().replace(/[.!?]+$/,'');return `${outcomeDraft.verb} ${t||'[content or task]'}${c?' '+c:''}.`}
function outcomeBuilder(){const b=studio.blooms.find(x=>x.level===outcomeDraft.level);modal('Make the learning visible.',`<p>Build one observable outcome and decide what evidence will show success.</p><span class="tiny-label">1 · CHOOSE A THINKING LEVEL</span><div class="bloom-picker">${studio.blooms.map(x=>`<button class="bloom-button ${x.level===b.level?'selected':''}" data-builder-level="${x.level}" aria-pressed="${x.level===b.level}">${x.level}</button>`).join('')}</div><div class="bloom-explanation"><strong>${b.level}</strong><p>${b.meaning}</p><small>The thinking required by the task matters more than the verb alone.</small></div><span class="tiny-label">2 · CHOOSE A VERB</span><div class="verb-picker">${b.verbs.map(v=>`<button class="chip ${v===outcomeDraft.verb?'active':''}" data-builder-verb="${v}">${v}</button>`).join('')}</div><div class="field"><label for="builder-topic">Content or task</label><input id="builder-topic" data-outcome-draft="topic" value="${esc(outcomeDraft.topic)}" placeholder="e.g. two workshop categories"></div><div class="field"><label for="builder-condition">Context or condition (optional)</label><input id="builder-condition" data-outcome-draft="condition" value="${esc(outcomeDraft.condition)}" placeholder="e.g. using the figures in a table"></div><div class="field"><label for="builder-evidence">Success evidence</label><textarea id="builder-evidence" data-outcome-draft="evidence" rows="2" placeholder="${esc(b.evidence)}">${esc(outcomeDraft.evidence)}</textarea></div><div class="outcome-preview"><span class="tiny-label">BY THE END OF THE LESSON, STUDENTS WILL BE ABLE TO…</span><p id="outcome-preview-text">${esc(outcomeSentence())}</p></div>${current?`<p class="current-lesson-label">Add to: <strong>${esc(current.name||'Your untitled lesson')}</strong></p>`:'<p>Open a lesson to add the outcome directly, or copy it to use elsewhere.</p>'}`,`<button class="btn btn-secondary" data-action="copy-outcome">${icon('copy')}Copy outcome</button><button class="btn btn-primary" data-action="add-outcome-built" ${!current?'disabled':''}>${icon('plus')}Add to lesson</button>`,'wide-dialog')}
function addBuiltOutcome(){if(!current)return;if(!outcomeDraft.topic.trim()||!outcomeDraft.evidence.trim()){toast('Add the content or task and its success evidence.');return}if(current.outcomes.length>=30)return toast('This lesson already has 30 outcomes.');const row=[outcomeSentence(),outcomeDraft.level,outcomeDraft.evidence.trim()];const empty=current.outcomes.findIndex(r=>r.every(c=>!c.trim()));if(empty>=0)current.outcomes[empty]=row;else current.outcomes.push(row);current.blooms=[...new Set([...current.blooms,outcomeDraft.level])];setDraft();closeModal();tab='edit';navigate('editor');$('#section-2')?.scrollIntoView({block:'start'});toast('Outcome and Bloom level added. Check the matching learning task.');}
function reviewChecks(p=current){if(!p)return [];const has=v=>typeof v==='string'&&v.trim().length>0;const outcomes=p.outcomes.filter(r=>r.some(has));const time=p.stages.reduce((s,r)=>s+(Number(r[0])||0),0);return [
{ok:has(p.name),title:'A clear lesson title',detail:has(p.name)?'Title provided. Check that it describes the learning purpose.':'Give the lesson a useful title.',section:1},
{ok:outcomes.length>0&&outcomes.every(r=>has(r[0])&&has(r[2])),title:'Evidence for every outcome',detail:'Each outcome needs an observable task and specific success evidence.',section:2},
{ok:outcomes.length>0&&!outcomes.some(r=>/^(understand|know|learn|be aware)\b/i.test(r[0].trim())),title:'Observable actions',detail:'If an outcome starts with “understand” or “know”, say how students will show that understanding.',section:2},
{ok:outcomes.length>0&&outcomes.every(r=>BLOOM.includes(r[1])&&p.blooms.includes(r[1])),title:'Consistent Bloom levels',detail:'Every outcome should have a level also selected in the lesson. Judge the level from the actual task.',section:3},
{ok:p.stages.length>0&&p.stages.every(r=>Number(r[0])>0&&has(r[1])&&has(r[2])&&has(r[3])),title:'Action and evidence in every stage',detail:'Give each stage a purpose, positive duration, teacher/student actions and learning evidence.',section:8},
{ok:time===Number(p.duration)&&time>0,title:'A realistic time budget',detail:`Your stages total ${time} minutes; the lesson duration is ${Number(p.duration)||0} minutes.`,section:8},
{ok:has(p.formative)&&has(p.final),title:'Checks during and after learning',detail:'Include a formative check with a teaching response, and a final task linked to the outcomes.',section:9},
{ok:has(p.support),title:'A route for learners who need support',detail:'Plan an appropriate scaffold and consider when to reduce it.',section:'support'},
{ok:has(p.resources),title:'Materials identified',detail:'Specify the resources learners and teacher will use.',section:5}
]}
function reviewLesson(){if(!current){modal('Start with a lesson.', '<p>Open a template or create a lesson, then review its outcomes, teaching sequence and assessment.</p>','<button class="btn btn-primary" data-nav="templates">Explore templates</button>');return}const checks=reviewChecks();const needs=checks.filter(x=>!x.ok).length;modal('Connect the learning.',`<div class="review-intro"><span class="review-symbol">${icon('check')}</span><div><strong>${needs?needs+' planning details to revisit':'The essential details are present'}</strong><p>These are content and timing checks, not a quality grade. Use your judgement to review alignment.</p></div></div><div class="review-list">${checks.map(x=>`<button class="review-item ${x.ok?'is-present':'needs-attention'}" data-fix-section="${x.section}"><span>${x.ok?icon('check'):icon('edit')}</span><div><strong>${x.title}</strong><p>${esc(x.detail)}</p></div>${icon('arrow')}</button>`).join('')}</div><details class="alignment-panel"><summary>Does the final task demonstrate the outcomes?</summary>${current.outcomes.map((r,i)=>`<div class="alignment-outcome"><strong>Outcome ${i+1}</strong><p>${esc(r[0]||'Not yet added')}</p><small>Evidence: ${esc(r[2]||'Not yet added')}</small></div>`).join('')}<div class="evidence-box"><strong>Final assessment</strong><p>${esc(current.final||'Not yet added')}</p></div><p>For each outcome, ask: Where do students practise it? What independent performance will show success? Do the final criteria match that performance?</p></details>`,`<button class="btn btn-secondary" data-action="close">Keep planning</button><button class="btn btn-primary" data-action="teach-mode">${icon('clock')}Open teaching view</button>`,'review-dialog')}
function sectionTip(n){const t=studio.tips[n-1];if(!t)return;modal(t.title,`<p>${t.body}</p><div class="evidence-box"><span class="tiny-label">A CLASSROOM EXAMPLE</span><p>${t.example}</p></div>`,n===2||n===3?'<button class="btn btn-primary" data-action="outcome-builder">Open outcome builder</button>':'<button class="btn btn-primary" data-action="close">Got it</button>')}
function quickActions(){modal('What would help right now?',`<div class="quick-action-grid"><button data-action="new">${icon('plus')}<strong>A new lesson</strong><span>Start with the essentials</span></button><button data-nav="templates">${icon('layers')}<strong>A ready-made example</strong><span>Six course starting points</span></button><button data-action="outcome-builder">${icon('spark')}<strong>A clearer outcome</strong><span>Action + task + evidence</span></button><button data-nav="toolkit">${icon('book')}<strong>A classroom activity</strong><span>Explore the teaching studio</span></button><button data-nav="worksheets">${icon('file')}<strong>A student handout</strong><span>Worksheets and teacher keys</span></button><button data-action="review-lesson">${icon('check')}<strong>A lesson review</strong><span>Look at the learning connections</span></button></div>`,'','wide-dialog')}
function samePlan(a,b){const x=clone(a),y=clone(b);delete x.updatedAt;delete y.updatedAt;return JSON.stringify(x)===JSON.stringify(y)}
function guardDraft(fn){const original=current&&saved.find(x=>x.id===current.id);if(!current||(original&&samePlan(original,current))){closeModal();fn();return}pendingDraftAction=fn;modal('Keep your current draft?',`<p>You’re working on <strong>${esc(current.name||'an untitled lesson')}</strong>. Save it before switching, or replace this draft. Your other saved lessons will stay in My lessons.</p>`,`<button class="btn btn-secondary" data-action="close">Keep editing</button><button class="btn btn-secondary" data-action="replace-draft">Replace draft</button>${current.name.trim()?'<button class="btn btn-primary" data-action="save-and-continue">Save & continue</button>':''}`)}
function continueDraft(saveFirst=false){if(saveFirst){saveLesson();if(!saved.some(p=>p.id===current.id&&samePlan(p,current)))return}const fn=pendingDraftAction;pendingDraftAction=null;closeModal();fn?.()}
function resetTeaching(index){stopTeaching();teaching.index=index;teaching.remaining=Math.max(0,Number(current.stages[index]?.[0])||0)*60000;teaching.planId=current.id}
function stopTeaching(){if(teaching.running)teaching.remaining=Math.max(0,teaching.deadline-Date.now());teaching.running=false;if(teaching.interval!==null){clearInterval(teaching.interval);teaching.interval=null}}
function clockText(ms){const s=Math.ceil(Math.max(0,ms)/1000);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function teachMode(){if(!current||!current.stages.length){modal('Bring a lesson into focus.','<p>Open a lesson with at least one teaching stage to use the teaching view and timer.</p>','<button class="btn btn-primary" data-nav="templates">Explore templates</button>');return}if(teaching.planId!==current.id||teaching.index>=current.stages.length)resetTeaching(0);const r=current.stages[teaching.index];modal(r[1]||'Teaching stage',`<div class="teach-meta"><span>${esc(current.name||'Your lesson')}</span><strong>STAGE ${teaching.index+1} / ${current.stages.length}</strong></div><div class="teach-layout"><div class="teach-clock"><span class="tiny-label">TIME FOR THIS STAGE</span><div id="teach-timer" role="timer" aria-live="off">${clockText(teaching.remaining)}</div><p id="teach-timer-status" role="status">${teaching.running?'Timer running':'Ready when you are'}</p><button class="btn btn-orange" data-action="toggle-timer" id="timer-toggle">${teaching.running?'Pause timer':'Start timer'}</button><button class="text-button" data-action="reset-timer">Reset this stage</button></div><div class="teach-instructions"><span class="tiny-label">TEACHER & STUDENT ACTIONS</span><p>${esc(r[2]||'Add the actions for this stage in your plan.')}</p><div class="evidence-box"><span class="tiny-label">LOOK / LISTEN FOR</span><p>${esc(r[3]||'Add the learning evidence for this stage.')}</p></div></div></div><p class="timer-note">The timer stops at zero. You decide when to move on.</p>`,`<button class="btn btn-secondary" data-teach-step="-1" ${teaching.index===0?'disabled':''}>${icon('back')}Previous stage</button><button class="btn btn-primary" data-teach-step="1" ${teaching.index===current.stages.length-1?'disabled':''}>Next stage ${icon('arrow')}</button>`,'teach-dialog')}
function tickTeaching(){if(!teaching.running)return;teaching.remaining=Math.max(0,teaching.deadline-Date.now());const el=$('#teach-timer');if(el)el.textContent=clockText(teaching.remaining);if(teaching.remaining===0){stopTeaching();const label=$('#teach-timer-status');if(label)label.textContent='Time is up. Continue when your class is ready.';const button=$('#timer-toggle');if(button)button.textContent='Start timer';toast('Stage time complete. Review the learning before moving on.')}}
function toggleTeaching(){if(teaching.running){stopTeaching();$('#timer-toggle').textContent='Resume timer';$('#teach-timer-status').textContent='Timer paused';return}if(teaching.remaining<=0){toast('Reset this stage to start its timer again.');return}teaching.running=true;teaching.deadline=Date.now()+teaching.remaining;teaching.interval=setInterval(tickTeaching,250);$('#timer-toggle').textContent='Pause timer';$('#teach-timer-status').textContent='Timer running'}

const actions={'quick-actions':quickActions,'outcome-builder':outcomeBuilder,'review-lesson':reviewLesson,'teach-mode':teachMode,'toggle-timer':toggleTeaching,'reset-timer':()=>{resetTeaching(teaching.index);teachMode()},'add-outcome-built':addBuiltOutcome,'copy-outcome':()=>{if(!outcomeDraft.topic.trim())return toast('Add the content or task first.');copyText(outcomeSentence()+'\nBloom: '+outcomeDraft.level+'\nEvidence: '+outcomeDraft.evidence)},'replace-draft':()=>continueDraft(false),'save-and-continue':()=>continueDraft(true),'worksheet-back':()=>navigate(worksheetReturn),'print-worksheet':()=>printWorksheet('student'),'print-key':()=>printWorksheet('key'),'worksheet-word':worksheetWord,new:newDialog,help,close:closeModal,resume:()=>{tab='edit';navigate('editor')},'create-blank':()=>{const code=$('#new-course').value;guardDraft(()=>newPlan(code,true))},save:saveLesson,'copy-all':()=>copyText(planText()),export:exportDialog,print:printPlan,word,text:()=>{download(planText(),'text/plain;charset=utf-8',filename()+'.txt');toast('Text version downloaded.')},backup:()=>backup(true),'backup-current':()=>backup(false),import:()=>$('#import-file').click(),'add-outcome':()=>{if(current.outcomes.length>=30)return toast('Use up to 30 outcomes per lesson.');current.outcomes.push(['','','']);setDraft();render();$('#field-outcomes-'+(current.outcomes.length-1)+'-0').focus()},'add-stage':()=>{if(current.stages.length>=50)return toast('Use up to 50 stages per lesson.');current.stages.push(['5','','','']);setDraft();render();$('#field-stages-'+(current.stages.length-1)+'-1').focus()},'fit-time':fitTime};
document.addEventListener('click',e=>{const b=e.target.closest('button,a[data-jump],a.brand');if(!b)return;if(b.matches('a.brand')){e.preventDefault();navigate('home');return}if(b.id==='menu-toggle'){const open=$('#sidebar').classList.toggle('open');b.setAttribute('aria-expanded',open);return}if(b.dataset.worksheet){worksheetPeek(b.dataset.worksheet);return}if(b.dataset.openWorksheet){openWorksheet(b.dataset.openWorksheet,b.dataset.returnTo||'worksheets');return}if(b.dataset.relatedWorksheet){worksheetPeek(b.dataset.relatedWorksheet,'editor');return}if(b.dataset.worksheetMode){worksheetMode=b.dataset.worksheetMode;render();return}if(b.dataset.nav){navigate(b.dataset.nav);return}if(b.dataset.action){actions[b.dataset.action]?.();return}
if(b.dataset.sectionTip){sectionTip(Number(b.dataset.sectionTip));return}
if(b.dataset.activity){activityPeek(b.dataset.activity);return}
if(b.dataset.activityCategory){activityCategory=b.dataset.activityCategory;render();return}
if(b.dataset.addActivity){addActivity(b.dataset.addActivity);return}
if(b.dataset.copyActivity){const a=studio.activities.find(x=>x.id===b.dataset.copyActivity);if(a)copyText(a.title+'\n'+a.steps.join('\n')+'\nEvidence: '+a.evidence+'\nPrepare: '+a.resources);return}
if(b.dataset.builderLevel){outcomeDraft.level=b.dataset.builderLevel;outcomeDraft.verb=studio.blooms.find(x=>x.level===outcomeDraft.level).verbs[0];outcomeBuilder();return}
if(b.dataset.builderVerb){outcomeDraft.verb=b.dataset.builderVerb;outcomeBuilder();return}
if(b.dataset.fixSection){closeModal();tab='edit';navigate('editor');$('#section-'+b.dataset.fixSection)?.scrollIntoView({block:'start'});return}
if(b.dataset.teachStep){const index=teaching.index+Number(b.dataset.teachStep);if(index>=0&&index<current.stages.length){resetTeaching(index);teachMode()}return}
if(b.dataset.template){lessonPeek(b.dataset.template);return}if(b.dataset.useTemplate){guardDraft(()=>newPlan(b.dataset.useTemplate));return}if(b.dataset.tab){tab=b.dataset.tab;setDraft();render();return}if(b.dataset.filter){filter=b.dataset.filter;$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x.dataset.filter===filter);x.setAttribute('aria-pressed',x.dataset.filter===filter)});if(page==='templates')$('#course-results').innerHTML=courseGrid();else $('#saved-results').innerHTML=filteredSaved();return}if(b.dataset.open){const p=saved.find(p=>p.id===b.dataset.open);if(p)guardDraft(()=>{current=clone(p);tab='edit';navigate('editor')});return}if(b.dataset.duplicate){const p=saved.find(p=>p.id===b.dataset.duplicate);if(p)guardDraft(()=>{current=clone(p);current.id=uid();current.name+=' (copy)';delete current.updatedAt;tab='edit';navigate('editor');toast('Copy opened. Select Save lesson to keep it.')});return}if(b.dataset.delete){confirmDelete(b.dataset.delete);return}if(b.dataset.confirmDelete){const next=saved.filter(p=>p.id!==b.dataset.confirmDelete);if(storageWrite(STORE,next)){saved=next;closeModal();render();toast('Saved lesson deleted.')}else toast('Unable to delete: browser storage is unavailable.');return}if(b.dataset.copyField){copyText(textSection(Number(b.dataset.copyField)));return}if(b.dataset.jump){e.preventDefault();if(tab==='preview'){tab='edit';render()}$('#section-'+b.dataset.jump)?.scrollIntoView({behavior:'smooth',block:'start'});return}if(b.dataset.removeOutcome!==undefined){current.outcomes.splice(Number(b.dataset.removeOutcome),1);setDraft();render();$('#section-2')?.scrollIntoView({block:'start'});return}if(b.dataset.removeStage!==undefined){current.stages.splice(Number(b.dataset.removeStage),1);setDraft();render();$('#section-8')?.scrollIntoView({block:'start'});return}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.outcomeDraft){outcomeDraft[t.dataset.outcomeDraft]=t.value;const preview=$('#outcome-preview-text');if(preview)preview.textContent=outcomeSentence();return}if(t.id==='search'){query=t.value;if(page==='templates')$('#course-results').innerHTML=courseGrid();else if(page==='saved')$('#saved-results').innerHTML=filteredSaved();return}if(t.dataset.path&&current){let val=t.value;if(t.dataset.path==='duration'){val=Number(val)||0;}setPath(t.dataset.path,val);if(t.dataset.path==='code')current.course=COURSES[val];scheduleDraft();updateStatus();}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.bloom){current.blooms=BLOOM.filter(b=>{const cb=$(`[data-bloom="${b}"]`);return cb?.checked});scheduleDraft();updateStatus()}if(t.dataset.path==='duration'){current.duration=Math.min(300,Math.max(5,Math.round(Number(current.duration)||60)));t.value=current.duration;scheduleDraft();updateStatus()}if(/^stages\.\d+\.0$/.test(t.dataset.path||'')){setPath(t.dataset.path,String(Math.min(300,Math.max(0,Math.round(Number(t.value)||0)))));t.value=getPath(t.dataset.path);scheduleDraft();updateStatus()}});
$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>5*1024*1024){toast('Choose a Lesson Rush backup smaller than 5 MB.');return}try{const data=JSON.parse(await f.text());if(data.app!=='Lesson Rush'||data.version!==1||!Array.isArray(data.lessons)||!data.lessons.length||data.lessons.length>500||!data.lessons.every(validPlan))throw Error('Invalid backup');const plans=data.lessons.map(p=>{const n=normalize(p);n.id=uid();n.updatedAt=new Date().toISOString();return n});const next=[...plans,...saved];if(!storageWrite(STORE,next)){toast('Import could not be saved. Download your current plans first.');return}saved=next;closeModal();navigate('saved');toast(`${plans.length} ${plans.length===1?'lesson':'lessons'} imported as new copies.`)}catch{toast('This file is not a valid Lesson Rush backup. No lessons changed.')}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();quickActions()}if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false')}});
$('#dialog').addEventListener('close',stopTeaching);
window.addEventListener('pagehide',()=>{stopTeaching();clearTimeout(draftTimer);setDraft()});
window.addEventListener('beforeprint',()=>{if(printOverride)return;if(page==='worksheet')$('#print-area').innerHTML=window.LessonRushWorksheets.html(worksheetCode,worksheetMode);else if(current)$('#print-area').innerHTML=planHTML(current)});
window.addEventListener('afterprint',()=>{printOverride=false});
window.lessonRush={navigate,toast,refresh:render,printCustom(html){printOverride=true;closeModal();$('#print-area').innerHTML=html;window.print();}};
render();
})();
